def choose_next(cur, left, tau, eta, alpha, beta, rng):
    left = np.asarray(left)
    w = tau[cur, left] ** alpha * eta[cur, left] ** beta     # «привабливість» кожної невідвіданої точки
    c = np.cumsum(w)                                         # рулетка: накопичені ваги
    k = int(np.searchsorted(c, rng.random() * c[-1], side='right'))
    return int(left[min(k, len(left) - 1)])

