def update_pheromone(tau, tours, lens, rho):
    new = (1.0 - rho) * tau                                  # випаровування; стара матриця не змінюється
    for g, L in zip(tours, lens):
        t = np.concatenate(([0], g, [0]))                    # вокзал → маршрут → вокзал
        new[t[:-1], t[1:]] += 1.0 / L                        # поповнюємо tau[i, j], а не tau[j, i]
    return new
